import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_source = r"""
#include <torch/extension.h>

torch::Tensor sigmoid_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("sigmoid", &sigmoid_cuda, "CUDA sigmoid");
}
"""

_cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void sigmoid_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int64_t n) {
    int64_t idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx < n) {
        const float v = x[idx];
        out[idx] = 1.0f / (1.0f + expf(-v));
    }
}

torch::Tensor sigmoid_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");

    c10::cuda::CUDAGuard device_guard(x.device());

    auto x_contiguous = x.contiguous();
    auto out = torch::empty_like(x_contiguous);
    const int64_t n = x_contiguous.numel();

    constexpr int threads = 256;
    const int blocks = static_cast<int>((n + threads - 1) / threads);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream(x.device().index());

    sigmoid_kernel<<<blocks, threads, 0, stream>>>(
        x_contiguous.data_ptr<float>(),
        out.data_ptr<float>(),
        n
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return out.view(x.sizes());
}
"""

_sigmoid_cuda = load_inline(
    name="custom_sigmoid_cuda",
    cpp_sources=_cpp_source,
    cuda_sources=_cuda_source,
    functions=None,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _sigmoid_cuda.sigmoid(x)

